from pathlib import Path
from zf.core.paths import state_path
from zf.cli import event_path


def test_relative():
    assert state_path(Path('/srv/demo'), 'runtime-data') == Path('/srv/demo/runtime-data')


def test_absolute():
    assert state_path(Path('/srv/demo'), '/review-absolute-state') == Path('/review-absolute-state')


def test_cli():
    assert event_path(Path('/srv/demo'), {'project': {'state_dir': '/review-absolute-state'}}) == Path('/review-absolute-state/events.jsonl')
